const meta = {
  component: Progress,
  parameters: {
    docs: {
      description: {
        component: "## Usage

Display task completion with a progress indicator, typically a progress bar.

**Import:** `@/registry/erbium/ui/progress`

## Usage

```tsx
import { Progress } from "@/registry/erbium/ui/progress";
```

```tsx
<Progress value={33} />
```

## Composition

Use `ProgressLabel` and `ProgressValue` to add a label and value display.

```tsx
import { Progress, ProgressLabel, ProgressValue } from "@/registry/erbium/ui/progress";

<Progress value={56} className="w-full max-w-sm">
  <ProgressLabel>Upload progress</ProgressLabel>
  <ProgressValue />
</Progress>;
```

```text
Progress
├── ProgressLabel
├── ProgressValue
└── ProgressTrack
    └── ProgressIndicator
```

For an operation without a known completion percentage, pass `value={null}` and give the progress bar an accessible label:

```tsx
<Progress value={null} aria-label="Uploading" />
```

## Base UI documentation

Explore the underlying primitives and their API reference.

- [Progress](https://base-ui.com/react/components/progress)",
      },
    },
    layout: "centered",
  },
  tags: ["autodocs"],
} satisfies Meta<typeof Progress>;

export default { ...meta, title: "Components/Progress",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

